extension Path {
    /// Scales a path drawn on `artboard` to fit `rect`, keeping its aspect ratio and centring it.
    func fitted(_ artboard: CGSize, in rect: CGRect) -> Path {
        let s = min(rect.width / artboard.width, rect.height / artboard.height)
        let dx = rect.minX + (rect.width - artboard.width * s) / 2
        let dy = rect.minY + (rect.height - artboard.height * s) / 2
        return applying(CGAffineTransform(a: s, b: 0, c: 0, d: s, tx: dx, ty: dy))
    }
}
